"""Product entry points. An area is not a claim of a validated scientific engine."""

AREAS = [
    {"id": "variants", "title": "Genetic variants", "method": "pten", "example": "Which measured PTEN substitutions have reduced activity with preserved abundance?", "inputs": "Pinned PTEN sequence, measurements and experimental reference structure", "evidence": "Audited activity and abundance assays with residue mapping", "limitations": "PTEN single substitutions only. No clinical classification or mutant folding."},
    {"id": "blood", "title": "Blood-group biology", "method": "blood", "example": "What does the evidence support about ABO and RhD separately in severe falciparum malaria?", "inputs": "Two reported ABO/RhD scenarios", "evidence": "Fixed inspected comparative literature corpus", "limitations": "No genotype, individual risk or infection simulation. Uploaded papers are context only for this method."},
    {"id": "cancer", "title": "Cancer biology", "method": "papers", "example": "What limitations does this paper report about a tumour signalling mechanism?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language passages", "limitations": "Document review only. No validated cancer analysis or patient predictions."},
    {"id": "immunity", "title": "Immunity", "method": "papers", "example": "Which immune pathway observations are reported in this paper?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language passages", "limitations": "Document review only. No immune-response simulation or clinical prediction."},
    {"id": "drugs", "title": "Drug mechanisms", "method": "papers", "example": "What evidence and limitations support the mechanism discussed in this paper?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language passages", "limitations": "Document review only. No synthesis, dosing or clinical recommendations."},
    {"id": "structure", "title": "Protein structure", "method": "pten", "example": "Where do measured PTEN substitutions map onto the experimental reference structure?", "inputs": "Pinned PTEN measurements and reference structure", "evidence": "Audited residue mapping and experimental coordinates", "limitations": "PTEN reference inspection only. No arbitrary structure upload, folding or docking."},
    {"id": "regulation", "title": "Gene regulation", "method": "papers", "example": "Which regulatory observations and competing explanations does this study report?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language passages", "limitations": "Document review only. No regulatory-network inference from new datasets."},
    {"id": "neuroscience", "title": "Neuroscience", "method": "papers", "example": "How does this paper support its proposed neural mechanism?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language passages", "limitations": "Document review only. No brain simulation or diagnostic analysis."},
    {"id": "comparative", "title": "Comparative biology", "method": "papers", "example": "Which comparisons are supported by the populations and methods in this paper?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language passages", "limitations": "Document review only. No cross-species sequence analysis engine."},
    {"id": "reproduction", "title": "Study reproduction", "method": "papers", "example": "What methods, missing inputs and limitations would matter when reproducing this study?", "inputs": "A supported paper with extracted text", "evidence": "Selected original-language methods passages", "limitations": "Methods review only. No automatic reproduction or experimental execution."},
]


def registry(available):
    return [dict(a, available=available(a["method"]), status=("Explore supported data" if a["method"] != "papers" else "Review papers") if available(a["method"]) else "Requires additional data", workflow={"pten": "PTEN variant investigation", "blood": "Blood-group evidence review", "papers": "Bounded paper review"}[a["method"]]) for a in AREAS]
